// Bit-exact decode parity in the browser: every fixture of the frozen parity
// sets (generated by `imij/examples/parity.rs`, sealed by tools/decode_parity.py;
// see scripts/prepare-fixtures.sh) is decoded through the worker pool and
// compared byte-for-byte against its native `.raw` samples. The wasm decoder
// must be identical to native on every tier — zero tolerance, not a <1/5000
// bound: `docs/DECODE_PARITY.md`.
//
// Package coverage (all four built by scripts/build-wasm.sh; the variant query
// forces one, `auto` exercises the pool's policy):
//   plain server    -> simd and relaxed, auto must pick relaxed when the
//                      relaxed-SIMD probe validates and simd otherwise
//   isolated server -> threads and relaxed-threads, auto likewise
//   strict server   -> threads under a restrictive CSP, incl. the preview path
//
// Every package decodes every fixture of the frozen sets (base, extra and
// superblocks); a relaxed package is skipped only when
// `WebAssembly.validate` rejects the relaxed probe module in that engine
// (the same detection the pool uses).
//
// Shards keep one test's runtime bounded; IMIJ_PARITY_SHARDS changes the count.
import { test, expect } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { PORTS } from '../playwright.config';

const FIXTURES = process.env.IMIJ_FIXTURES || join(homedir(), 'tmp', 'imij-web-fixtures');
const SHARDS = Number(process.env.IMIJ_PARITY_SHARDS ?? 4);

type Entry = {
  name: string;
  width: number;
  height: number;
  channels: string;
  sample: string;
  lossless: string;
  kind: string;
  frames: string;
};

function loadManifest(sub: string): Entry[] {
  const text = readFileSync(join(FIXTURES, sub, 'fixtures.tsv'), 'utf8');
  const lines = text.trim().split('\n');
  const header = lines[0].split('\t');
  const col = (name: string) => header.indexOf(name);
  return lines.slice(1).map((line) => {
    const f = line.split('\t');
    return {
      name: f[col('name')],
      width: Number(f[col('width')]),
      height: Number(f[col('height')]),
      channels: f[col('channels')],
      sample: f[col('sample')],
      lossless: f[col('lossless')],
      kind: f[col('kind')],
      frames: f[col('frames')] ?? '',
    };
  });
}

const base = loadManifest('base');
const extra = loadManifest('extra');
const superblocks = loadManifest('superblocks');

function shard<T>(items: T[], i: number): T[] {
  const per = Math.ceil(items.length / SHARDS);
  return items.slice(i * per, (i + 1) * per);
}

async function runShard(page, port: number, sub: string, entries: Entry[], query = '') {
  await page.goto(`http://127.0.0.1:${port}/tests/fixtures/decode.html${query}`);
  await page.evaluate(() => window.__ready);
  return page.evaluate(
    ({ entries, basePath }) => window.__decodeAll(entries, basePath),
    { entries, basePath: `/fixtures/${sub}` },
  );
}

// The relaxed probe runs while constructing a pool; any page reports it.
async function relaxedSupported(page, port: number): Promise<boolean> {
  await page.goto(`http://127.0.0.1:${port}/tests/fixtures/decode.html`);
  return page.evaluate(() => window.__relaxedSupported);
}

function expectClean(r, shardEntries: Entry[], testInfo) {
  const detail = (o) => JSON.stringify(o, null, 1);
  if (r.metadata.length) testInfo.attach('metadata-mismatches', { body: detail(r.metadata), contentType: 'application/json' });
  if (r.mismatches.length) testInfo.attach('pixel-mismatches', { body: detail(r.mismatches), contentType: 'application/json' });
  expect(r.metadata, 'decoder metadata must match the fixture manifest').toEqual([]);
  expect(r.failed, 'every decoded sample must be bit-identical to the native .raw').toBe(0);
  expect(r.total).toBe(shardEntries.length);
}

for (let i = 0; i < SHARDS; i++) {
  test(`base fixtures ${i + 1}/${SHARDS} via simd (plain server, no isolation)`, async ({ page }, testInfo) => {
    const entries = shard(base, i);
    testInfo.setTimeout(Math.max(180_000, entries.length * 300));
    const r = await runShard(page, PORTS.plain, 'base', entries, '?variant=simd');
    expect(r.variant).toBe('simd');
    expect(r.tier).toBe('wasm128');
    expectClean(r, entries, testInfo);
  });
}

for (let i = 0; i < SHARDS; i++) {
  test(`base fixtures ${i + 1}/${SHARDS} via relaxed (plain server, no isolation)`, async ({ page }, testInfo) => {
    if (!(await relaxedSupported(page, PORTS.plain))) test.skip(true, 'engine rejects the relaxed-SIMD probe');
    const entries = shard(base, i);
    testInfo.setTimeout(Math.max(180_000, entries.length * 300));
    const r = await runShard(page, PORTS.plain, 'base', entries, '?variant=relaxed');
    expect(r.variant).toBe('relaxed');
    expect(r.tier).toBe('wasm128');
    expectClean(r, entries, testInfo);
  });
}

for (let i = 0; i < SHARDS; i++) {
  test(`base fixtures ${i + 1}/${SHARDS} via threads (isolated server)`, async ({ page }, testInfo) => {
    const entries = shard(base, i);
    testInfo.setTimeout(Math.max(180_000, entries.length * 300));
    const r = await runShard(page, PORTS.isolated, 'base', entries, '?variant=threads');
    expect(r.variant).toBe('threads');
    expect(r.tier).toBe('wasm128');
    expectClean(r, entries, testInfo);
  });
}

for (let i = 0; i < SHARDS; i++) {
  test(`base fixtures ${i + 1}/${SHARDS} via relaxed-threads (isolated server)`, async ({ page }, testInfo) => {
    if (!(await relaxedSupported(page, PORTS.isolated))) test.skip(true, 'engine rejects the relaxed-SIMD probe');
    const entries = shard(base, i);
    testInfo.setTimeout(Math.max(180_000, entries.length * 300));
    const r = await runShard(page, PORTS.isolated, 'base', entries, '?variant=relaxed-threads');
    expect(r.variant).toBe('relaxed-threads');
    expect(r.tier).toBe('wasm128');
    expectClean(r, entries, testInfo);
  });
}

// Superblock files (merged 16x16 / 16x8 / 8x16 DCTs, SPEC 2.9) through every
// package.
for (const [variant, port] of [
  ['simd', PORTS.plain],
  ['relaxed', PORTS.plain],
  ['threads', PORTS.isolated],
  ['relaxed-threads', PORTS.isolated],
] as const) {
  test(`superblock fixtures via ${variant}`, async ({ page }, testInfo) => {
    if (variant.startsWith('relaxed') && !(await relaxedSupported(page, port))) {
      test.skip(true, 'engine rejects the relaxed-SIMD probe');
    }
    testInfo.setTimeout(Math.max(180_000, superblocks.length * 300));
    const r = await runShard(page, port, 'superblocks', superblocks, `?variant=${variant}`);
    expect(r.variant).toBe(variant);
    expect(r.tier).toBe('wasm128');
    expectClean(r, superblocks, testInfo);
  });
}

test('strict CSP server: threads package decodes and the preview canvas renders', async ({ page }, testInfo) => {
  const entries = base.slice(0, 64);
  testInfo.setTimeout(120_000);
  const r = await runShard(page, PORTS.strict, 'base', entries, '?variant=threads');
  expect(r.variant).toBe('threads');
  expectClean(r, entries, testInfo);
  await page.goto(`http://127.0.0.1:${PORTS.strict}/tests/fixtures/decode.html`);
  await page.evaluate(() => window.__ready);
  const render = await page.evaluate((name) => window.__decodeAndRender(`/fixtures/base/${name}.imi`), entries[0].name);
  expect(render.rgba).toBeGreaterThan(0);
});

// The pool's auto policy: relaxed when the probe validates, the strict
// package otherwise; threads variants on a cross-origin isolated page.
test('auto package selection follows the relaxed-SIMD probe (plain server)', async ({ page }) => {
  await page.goto(`http://127.0.0.1:${PORTS.plain}/tests/fixtures/decode.html`);
  const ready = await page.evaluate(() => window.__ready);
  const supported = await page.evaluate(() => window.__relaxedSupported);
  expect(ready[0].ok, JSON.stringify(ready)).toBe(true);
  expect(ready[0].variant).toBe(supported ? 'relaxed' : 'simd');
});

test('auto package selection follows the relaxed-SIMD probe (isolated server)', async ({ page }) => {
  await page.goto(`http://127.0.0.1:${PORTS.isolated}/tests/fixtures/decode.html`);
  const ready = await page.evaluate(() => window.__ready);
  const supported = await page.evaluate(() => window.__relaxedSupported);
  expect(ready[0].ok, JSON.stringify(ready)).toBe(true);
  expect(ready[0].variant).toBe(supported ? 'relaxed-threads' : 'threads');
});

// The decode schedule can only run parallel if the rayon pool is really up:
// `?threads=N` must reach initThreadPool (the decoder's whole-pool budget is N).
test('threads package reports the initialized rayon pool size', async ({ page }) => {
  await page.goto(`http://127.0.0.1:${PORTS.isolated}/tests/fixtures/decode.html?variant=threads&threads=4`);
  const ready = await page.evaluate(() => window.__ready);
  expect(ready[0].ok, JSON.stringify(ready)).toBe(true);
  expect(ready[0].variant).toBe('threads');
  expect(ready[0].threads).toBe(4);
  expect(ready[0].tier).toBe('wasm128');
});

test('simd package has no rayon pool (single-threaded)', async ({ page }) => {
  await page.goto(`http://127.0.0.1:${PORTS.plain}/tests/fixtures/decode.html?variant=simd`);
  const ready = await page.evaluate(() => window.__ready);
  expect(ready[0].ok, JSON.stringify(ready)).toBe(true);
  expect(ready[0].variant).toBe('simd');
  expect(ready[0].threads).toBe(1);
});

// Frames/pages/palette-boundary extension: every frame decoded onto its
// canvas, rows concatenated exactly like `extra.rs::frame_pixels`, at padding
// 0 and 13; headers and kind compared with the manifest.
const EXTRA_SHARDS = Math.max(1, Math.min(SHARDS, 4));

async function extraShard(page, port: number, i: number, query: string) {
  const entries = extra.filter((_, j) => j % EXTRA_SHARDS === i);
  await page.goto(`http://127.0.0.1:${port}/tests/fixtures/decode.html${query}`);
  await page.evaluate(() => window.__ready);
  return page.evaluate(
    ({ entries, basePath }) => window.__decodeAll(entries, basePath, { paddings: [0, 13] }),
    { entries, basePath: '/fixtures/extra' },
  );
}

for (let i = 0; i < EXTRA_SHARDS; i++) {
  test(`extra fixtures ${i + 1}/${EXTRA_SHARDS} via threads (isolated server)`, async ({ page }, testInfo) => {
    testInfo.setTimeout(Math.max(180_000, 582 * 400));
    const entries = extra.filter((_, j) => j % EXTRA_SHARDS === i);
    const r = await extraShard(page, PORTS.isolated, i, '?variant=threads');
    expect(r.variant).toBe('threads');
    expectClean(r, entries, testInfo);
  });
}

for (let i = 0; i < EXTRA_SHARDS; i++) {
  test(`extra fixtures ${i + 1}/${EXTRA_SHARDS} via relaxed-threads (isolated server)`, async ({ page }, testInfo) => {
    if (!(await relaxedSupported(page, PORTS.isolated))) test.skip(true, 'engine rejects the relaxed-SIMD probe');
    testInfo.setTimeout(Math.max(180_000, 582 * 400));
    const entries = extra.filter((_, j) => j % EXTRA_SHARDS === i);
    const r = await extraShard(page, PORTS.isolated, i, '?variant=relaxed-threads');
    expect(r.variant).toBe('relaxed-threads');
    expectClean(r, entries, testInfo);
  });
}

test('extra fixtures via simd (plain server)', async ({ page }, testInfo) => {
  testInfo.setTimeout(300_000);
  const r = await runShard(page, PORTS.plain, 'extra', extra, '?variant=simd');
  expect(r.variant).toBe('simd');
  expectClean(r, extra, testInfo);
});

test('extra fixtures via relaxed (plain server)', async ({ page }, testInfo) => {
  if (!(await relaxedSupported(page, PORTS.plain))) test.skip(true, 'engine rejects the relaxed-SIMD probe');
  testInfo.setTimeout(300_000);
  const r = await runShard(page, PORTS.plain, 'extra', extra, '?variant=relaxed');
  expect(r.variant).toBe('relaxed');
  expectClean(r, extra, testInfo);
});
